SELECT table_schema, table_name FROM information_schema.tables
WHERE table_schema NOT IN ('pg_catalog','information_schema')
ORDER BY 1,2;

SELECT n.nspname, c.relname, c.relkind FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
WHERE n.nspname IN ('public','store','warehouse','payments') AND c.relkind IN ('r','v','m','f','p')
ORDER BY 1,2;

SELECT table_name, column_name, data_type FROM information_schema.columns
WHERE table_schema='store' AND table_name IN ('goods_receipts','fresh_deliveries','forecasts','inventory_book','store_orders')
ORDER BY table_name, ordinal_position;

SELECT table_schema, table_name, column_name FROM information_schema.columns
WHERE table_schema IN ('store','warehouse','payments') AND (column_name ~* 'cust|member|phone|loyal|name')
ORDER BY 1,2,3;

SELECT tender, till_status, count(*) n, min(ts) mn, max(ts) mx
FROM payments.pos_payments
GROUP BY 1,2 ORDER BY 1,2;

SELECT date_trunc('day', bill_ts)::date d,
       count(*) lines, count(DISTINCT bill_id) bills
FROM store.pos_lines GROUP BY 1 ORDER BY 1;

-- Explore stock_adjustments, stock_counts triggers, write_offs detail
SELECT * FROM warehouse.stock_adjustments;
SELECT trigger, count(*), sum(adjustment) FROM store.stock_counts GROUP BY trigger;
SELECT * FROM store.write_offs ORDER BY date LIMIT 40;

-- Q3/Q4: payments overview
SELECT tender, till_status, count(*) AS n, sum(amount_inr) AS amt
FROM payments.pos_payments
GROUP BY tender, till_status ORDER BY tender, till_status;
SELECT status, count(*) FROM payments.psp_upi_report GROUP BY status;
SELECT kind, count(*), sum(amount_inr) FROM payments.customer_complaints GROUP BY kind;
SELECT trigger, count(*), sum(amount_inr) FROM payments.upi_refunds GROUP BY trigger;

SELECT tender, till_status, count(*) AS n, sum(amount_inr) AS amt
FROM payments.pos_payments
GROUP BY tender, till_status ORDER BY tender, till_status;

SELECT status, count(*) FROM payments.psp_upi_report GROUP BY status;
SELECT kind, count(*), sum(amount_inr) FROM payments.customer_complaints GROUP BY kind;
SELECT trigger, count(*), sum(amount_inr) FROM payments.upi_refunds GROUP BY trigger;
SELECT note, count(*) FROM payments.pos_payments GROUP BY note ORDER BY 2 DESC LIMIT 20;

-- Q8: sales of atta packs over time
SELECT date, sku, units_sold, revenue_inr FROM store.daily_sales
WHERE sku LIKE 'ATTA%' ORDER BY sku, date;

-- Q8: monthly totals for atta packs + shelf audit status for atta
SELECT sku, sum(units_sold) units, sum(revenue_inr) rev, round(sum(revenue_inr)/sum(units_sold),2) avg_price
FROM store.daily_sales WHERE sku LIKE 'ATTA%' GROUP BY sku ORDER BY sku;
SELECT sku, status, count(*) FROM store.shelf_audits WHERE sku LIKE 'ATTA%' GROUP BY 1,2 ORDER BY 1,2;

-- Q8: shelf audit empties for atta + inventory book for atta
SELECT audit_ts, sku, status FROM store.shelf_audits WHERE sku LIKE 'ATTA%' AND status='empty' ORDER BY audit_ts;
SELECT date, sku, book_on_hand_close FROM store.inventory_book WHERE sku LIKE 'ATTA%' ORDER BY sku, date;

-- goods_receipts full columns and sample
SELECT * FROM store.goods_receipts ORDER BY received_ts LIMIT 15;
SELECT receipt_method, count(*) FROM store.goods_receipts GROUP BY 1;
SELECT route, count(*) FROM store.fresh_deliveries GROUP BY 1;

-- Q5: fresh deliveries with use_by for milk
SELECT * FROM store.fresh_deliveries WHERE sku LIKE 'MILK%' ORDER BY delivery_ts LIMIT 20;
SELECT sku, count(*) lines, sum(units) units, min(use_by) min_ub, max(use_by) max_ub FROM store.fresh_deliveries GROUP BY sku;

-- Q8: shelf audit empties (all SKUs) with dates
SELECT audit_ts, sku, status FROM store.shelf_audits WHERE status='empty' ORDER BY audit_ts;
-- Q5 context: milk expired write-offs
SELECT sku, sum(units) expired_units FROM store.write_offs WHERE reason='expired' AND sku LIKE 'MILK%' GROUP BY sku;
-- Q4 context: tender mix by amount (June)
SELECT tender, count(*) FILTER (WHERE till_status='approved') approved_attempts,
       sum(amount_inr) FILTER (WHERE till_status='approved') approved_amt
FROM payments.pos_payments GROUP BY tender ORDER BY approved_amt DESC;

-- Q8: 5kg vs 1kg atta around the 26 Jun count event; shelf empties; mirror-image correction
SELECT date, sku, units_sold, revenue_inr FROM store.daily_sales
WHERE sku IN ('ATTA-WW-5KG','ATTA-WW-1KG') AND date >= DATE '2026-06-18' ORDER BY date, sku;
SELECT audit_ts, sku, status FROM store.shelf_audits WHERE sku LIKE 'ATTA%' AND status='empty' ORDER BY audit_ts;
SELECT sc.count_ts, sc.sku, sc.book_before, sc.counted, sc.adjustment, sc.trigger, sa.slot, sa.cases, sa.units, sa.reason
FROM store.stock_counts sc LEFT JOIN warehouse.stock_adjustments sa ON sa.sku=sc.sku
WHERE sc.sku LIKE 'ATTA%' AND sc.count_ts >= DATE '2026-06-26' ORDER BY sc.sku;

SELECT table_schema, table_name FROM information_schema.tables
WHERE table_schema NOT IN ('pg_catalog','information_schema')
ORDER BY 1,2;

SELECT DISTINCT trigger FROM payments.upi_refunds;
SELECT DISTINCT status FROM payments.psp_upi_report;
SELECT DISTINCT till_status FROM payments.pos_payments;
SELECT DISTINCT kind FROM payments.customer_complaints;
SELECT DISTINCT resolution FROM payments.customer_complaints;

SELECT count(DISTINCT shipment_id) AS grn_shipments, count(*) AS grn_lines, count(DISTINCT grn_id) AS grns
FROM store.goods_receipts;
SELECT count(DISTINCT shipment_id) FROM warehouse.shipping_notice_lines;
SELECT count(DISTINCT shipment_id) FROM warehouse.pick_confirmations;

SELECT bill_ts, qty FROM store.pos_lines
WHERE sku_scanned='ATTA-WW-5KG' AND bill_ts::date BETWEEN '2026-06-11' AND '2026-06-14'
ORDER BY bill_ts;

SELECT table_schema, table_name FROM information_schema.tables
WHERE table_schema NOT IN ('pg_catalog','information_schema')
ORDER BY 1,2;

SELECT 'pos_lines' src, count(DISTINCT bill_id) bills, min(bill_ts)::text mn, max(bill_ts)::text mx FROM store.pos_lines
UNION ALL SELECT 'pos_payments', count(DISTINCT bill_id), min(ts)::text, max(ts)::text FROM payments.pos_payments
UNION ALL SELECT 'psp', count(DISTINCT bill_ref), min(initiated_ts)::text, max(initiated_ts)::text FROM payments.psp_upi_report;

SELECT count(DISTINCT bill_id) AS bills_june_lines, count(*) AS lines_june
FROM store.pos_lines
WHERE bill_ts >= '2026-06-01' AND bill_ts < '2026-07-01';

SELECT count(DISTINCT bill_id) AS bills_june_pay, count(*) AS attempts_june, count(DISTINCT rrn) AS rrns
FROM payments.pos_payments
WHERE ts >= '2026-06-01' AND ts < '2026-07-01';

SELECT sum(units) AS expired_units_june, count(*) AS rows
FROM store.write_offs
WHERE reason = 'expired' AND date >= '2026-06-01' AND date < '2026-07-01';

SELECT count(*) rows, count(gtin_scanned) gtin_nonnull, count(sku_scanned) sku_nonnull,
       count(DISTINCT bill_id) bills, count(DISTINCT gtin_scanned) gtins
FROM store.pos_lines;

SELECT lines_per_bill, count(*) bills FROM (
  SELECT bill_id, count(*) lines_per_bill FROM store.pos_lines GROUP BY 1) t
GROUP BY 1 ORDER BY 1;
